2 (1961)\n# etc.\n\n# Print sample to understand\nfor i, (month, nums) in enumerate(all_data[:15]):\n    print(f\"Row {i}: {month} -> Treasury: {nums[0] if len(nums)>0 else 'N/A'}, Aa: {nums[1] if len(nums)>1 else 'N/A'}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
