.', 'Apr.', 'May', 'June', 'July', 'Aug.', 'Sept.', 'Oct.', 'Nov.', 'Dec.']\n\nall_data = []\nfor line in lines:\n    for month in months:\n        if '| ' + month + ' |' in line:\n            parts = line.split('|')\n            nums = []\n            for p in parts:\n                p = p.strip()\n                match = re.match(r'^(\\d+\\.\\d+)', p)\n                if match:\n                    nums.append(float(match.group(1)))\n            if nums and len(nums) >= 12:\n                all_data.append(nums[:12])\n\nprint(f\"Total months: {len(all_data)}\")\n\n# Looking at the structure:\n# The columns represent different periods (years) shown in parallel\n# Cols 0-2: Period 1 (first year in the table)\n# Cols 3-5: Period 2 \n# Cols 6-8: Period 3\n# Cols 9-11: Period 4\n\n# The key is to figure out which years these correspond to\n# Based on the yields:\n\n# Let's check each column group's full year data (all 12 months)\n# If we have 12 months for each column group, then we have 4 years\n\n# But we need 10 years (1960-1969). Let me check the .3 columns\n# which seem to have much higher yields\n\n# Looking at Treasury yields:\n# Col 0: 3.91 -> 4.27 (typical 1960)\n# Col 3: 4.08 -> 3.87 (typical 1961)\n# Col 6: 4.14 -> 4.43 (typical 1962)\n# Col 9: 5.18 -> increasing (likely 1963-1964 or later)\n\n# Actually, I realize now this table might only show 4 representative years\n# and the rest might be elsewhere\n\n# Let me check if there are more columns I'm missing - maybe there's a second table\n# Or maybe the footnotes give us more info\n\n# Looking at the footnote: \"Treasury series based on reoffering yields of new corporate bonds rated Aa by Moody's\"\n# This suggests this table is specifically about bond yields\n\n# Let me think about this differently:\n# - The first column group shows 1960 data (based on yields ~4%)\n# - The second shows 1961 (~4%)\n# - The third shows 1962 (~4%)\n# - The fourth shows values that are too high for 1963 (which was ~4%)\n\n# Actually wait - I should look at all 12 months for col 9 to see the pattern\nprint(\"\\nColumn 9 (Treasury.3) - all 12 months:\")\nfor i, nums in enumerate(all_data[:12]):\n    print(f\"  Month {i+1}: {nums[9]}\")\n\n# Same for column 10 (Aa.3)\nprint(\"\\nColumn 10 (Aa corporate.3) - all 12 months:\")\nfor i, nums in enumerate(all_data[:12]):\n    print(f\"  Month {i+1}: {nums[10]}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
