lculate spreads for each column group\n\n# First, the spread = Aa corporate yield - Treasury yield\n# For first year (col 0,1,2): spread = 4.58 - 3.91 = 0.67%\n# For second year (col 3,4,5): spread = 4.56 - 4.08 = 0.48%\n# For third year (col 6,7,8): spread = 4.45 - 4.14 = 0.31%\n# For fourth year (col 9,10,11): spread = 6.57 - 5.18 = 1.39%\n\n# The fourth year spread is MUCH larger - this is consistent with later years\n\n# Let me see all the spreads to map to years\n# I'll calculate spread for each \"column group\" across all the available data\n\nprint(\"\\nCalculating yield spreads by column groups:\")\nfor grp in range(4):\n    start_row = 0\n    treasury_col = grp * 3\n    aa_col = grp * 3 + 1\n    \n    print(f\"\\nColumn Group {grp}:\")\n    print(f\"  Treasury col {treasury_col}, Aa col {aa_col}\")\n    \n    # Look at rows in the first year block (rows 0-11)\n    for row_idx in range(12):\n        if row_idx < len(data):\n            treasury = data[row_idx][treasury_col]\n            aa = data[row_idx][aa_col]\n            if treasury and aa:\n                spread = aa - treasury\n                print(f\"  Month {row_idx+1}: T={treasury}, Aa={aa}, Spread={spread:.2f}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
